// phpcs:disable PSR1.Classes.ClassDeclaration.MissingNamespace, Squiz.Classes.ValidClassName.NotCamelCaps
if (!class_exists('TagGroups_Icons')) {
    /**
     * Icons that can be assigned to tags
     *
     * The icons are a curated subset of Font Awesome Free, stored in include/helpers/icons/fontawesome-icons.php
     * (generated by bin/build-icons.py) and written into the page as inline SVG, so no icon font or CDN is loaded.
     * A tag stores only the icon key, e.g. 'fas fa-utensils'.
     */
    class TagGroups_Icons
    {
        /**
         * Term meta key of the icon
         */
        const META_KEY = '_tg_icon';

        /**
         * @var array|null key => array( label, viewBox, path )
         */
        private static $icons = null;

        /**
         * All available icons
         *
         * @return array
         */
        public static function get_all()
        {
            if (null === self::$icons) {
                self::$icons = include dirname(__FILE__) . '/icons/fontawesome-icons.php';
                if (!is_array(self::$icons)) {
                    self::$icons = array();
                }
            }

            return self::$icons;
        }

        /**
         * Whether an icon key is available
         *
         * @param string $key
         * @return bool
         */
        public static function exists($key)
        {
            $icons = self::get_all();

            return is_string($key) && isset($icons[ $key ]);
        }

        /**
         * Returns the key if it is available, otherwise an empty string
         *
         * @param mixed $key
         * @return string
         */
        public static function sanitize($key)
        {
            if (!is_string($key)) {
                return '';
            }

            $key = trim(preg_replace('/\s+/', ' ', $key));

            return self::exists($key) ? $key : '';
        }

        /**
         * Inline SVG of an icon, hidden from screen readers because the tag name follows
         *
         * @param string $key
         * @param string $class
         * @return string
         */
        public static function get_svg($key, $class = 'tag-groups-icon')
        {
            if (!self::exists($key)) {
                return '';
            }

            $icon = self::$icons[ $key ];

            return '<svg class="' . esc_attr($class) . '" xmlns="http://www.w3.org/2000/svg" viewBox="' . esc_attr($icon[1]) . '" aria-hidden="true" focusable="false"><path d="' . esc_attr($icon[2]) . '"/></svg>';
        }

        /**
         * Icon key of a tag, or an empty string
         *
         * @param int $term_id
         * @return string
         */
        public static function get_term_icon($term_id)
        {
            return self::sanitize(get_term_meta((int) $term_id, self::META_KEY, true));
        }

        /**
         * Saves or removes the icon of a tag
         *
         * @param int $term_id
         * @param string $key
         * @return void
         */
        public static function set_term_icon($term_id, $key)
        {
            $key = self::sanitize($key);

            if ('' === $key) {
                delete_term_meta((int) $term_id, self::META_KEY);
            } else {
                update_term_meta((int) $term_id, self::META_KEY, $key);
            }
        }
    }
}
